package com.dunerealms.staff;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.configuration.file.YamlConfiguration;
import java.io.File;import java.sql.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.math.BigDecimal;import java.security.MessageDigest;

/** Assigned case tools; item/economy changes commit only through Core's target profile checkpoint. */
public final class DuneStaff extends JavaPlugin implements CommandExecutor {
 private JavaPlugin core;private CoreFence fence;private CaseBridge bridge;private Driver driver;private Properties auth;private String url;private volatile boolean ready;
 private final CaseStore store=new CaseStore();private final Set<UUID> busy=new HashSet<>();
 private final ExecutorService worker=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"DuneStaff-private-reader");t.setDaemon(true);return t;});
 @Override public void onEnable(){getCommand("dunecase").setExecutor(this);try{
  core=(JavaPlugin)getServer().getPluginManager().getPlugin("DuneCore");fence=new CoreFence(core);url=core.getConfig().getString("database.jdbc-url","");if(!url.startsWith("jdbc:mysql:"))throw new IllegalStateException();
  auth=new Properties();auth.setProperty("user",core.getConfig().getString("database.username",""));auth.setProperty("password",core.getConfig().getString("database.password",""));auth.setProperty("connectTimeout","3000");auth.setProperty("socketTimeout","5000");auth.setProperty("allowPublicKeyRetrieval","true");
  driver=(Driver)Class.forName("com.mysql.cj.jdbc.Driver",true,core.getClass().getClassLoader()).getDeclaredConstructor().newInstance();
  JavaPlugin ess=(JavaPlugin)getServer().getPluginManager().getPlugin("DuneEss");YamlConfiguration cfg=YamlConfiguration.loadConfiguration(new File(ess.getDataFolder(),"website-bridge.yml"));bridge=new CaseBridge(cfg.getString("origin",""),cfg.getString("secret",""));
  worker.execute(()->{try(Connection c=connect()){CaseStore.initialize(c);ready=true;getLogger().info("Assigned case tools ready; all target actions require current SQL authority.");}catch(Exception e){getLogger().severe("Case audit schema unavailable; staff actions disabled.");}});
 }catch(Exception e){getLogger().severe("Verified Core database and website bridge required; case tools disabled.");}}
 @Override public void onDisable(){ready=false;worker.shutdownNow();busy.clear();}
 private Connection connect()throws SQLException{Connection c=driver.connect(url,auth);if(c==null)throw new SQLException("Private SQL unavailable");return c;}
 private void main(Runnable r){if(isEnabled())getServer().getScheduler().runTask(this,r);}
 private boolean entry(Player p){return ready&&CaseGuards.entry(p);}
 private Screens.Choice choice(Player p,String label,String body,Runnable callback){return new Screens.Choice(label,body,()->{if(entry(p))callback.run();else p.sendMessage("Case access changed. Open a fresh case menu.");});}
 private void show(Player p,String title,String body,List<Screens.Choice> choices){if(entry(p))Screens.show(this,p,title,body,choices);}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)||!entry(p)){sender.sendMessage("Current staff ticket permission and verified case services required.");return true;}if(args.length==0)tickets(p);else if(args.length==1&&args[0].matches("[1-9][0-9]{0,17}"))openCase(p,Long.parseLong(args[0]));else p.sendMessage("Use /dunecase [ticket-id].");return true;}
 private <T>void read(Player p,String title,Callable<T> operation,Consumer<T> callback){
  if(!entry(p)||!busy.add(p.getUniqueId()))return;Inventory model=Screens.loading(this,p,title);UUID id=p.getUniqueId();
  worker.execute(()->{T result=null;try{result=operation.call();}catch(Exception unavailable){/* Do not log private context, responses or bridge credentials. */}T value=result;main(()->{busy.remove(id);if(!entry(p)||!Screens.current(p,model))return;if(value==null){p.sendMessage("Case information could not be confirmed. No target action was performed.");return;}callback.accept(value);});});
 }
 private void tickets(Player p){read(p,"Staff Cases · Loading",()->bridge.tickets(p.getUniqueId()),rows->{List<Screens.Choice> choices=new ArrayList<>();for(var row:rows)choices.add(choice(p,"#"+row.number()+" · "+row.subject(),"Open canonical case #"+row.id(),()->openCase(p,row.id())));if(choices.isEmpty())choices.add(choice(p,"Refresh","No cases are visible in your current departments.",()->tickets(p)));show(p,"Staff Cases","Current department and native ticket visibility are checked by the canonical Support Center.",choices);});}
 public void openCase(Player p,long ticket){if(!entry(p)||ticket<=0)return;read(p,"Case · Loading",()->bridge.context(p.getUniqueId(),ticket,"read",0,null),context->caseMenu(p,context));}
 private void caseMenu(Player p,CaseBridge.Context c){
  List<Screens.Choice> choices=new ArrayList<>();
  if(c.take())choices.add(choice(p,"Take this case","Assign this open ticket to your mapped agent; current department access checked again.",()->mutate(p,c,"take",null)));
  if(c.setSuspect()&&CaseGuards.entry(p))choices.add(choice(p,"Set suspect","Choose a real currently online Minecraft identity.",()->suspects(p,c)));
  if(p.getUniqueId().equals(c.assigned())&&CaseGuards.action(p)){
   if(c.teleport()&&c.creator()!=null)choices.add(choice(p,"Go to creator","Current online creator UUID: "+c.creator(),()->teleport(p,c,true)));
   if(c.teleport()&&c.suspect()!=null)choices.add(choice(p,"Go to suspect","Current online suspect UUID: "+c.suspect(),()->teleport(p,c,false)));
   if(c.inspect()&&c.suspect()!=null)choices.add(choice(p,"Inspect suspect inventory","Read the exact online suspect's current slots under the case lock.",()->inventory(p,c)));
   if(c.faction()&&c.suspect()!=null)choices.add(choice(p,"Change suspect faction","Choose a canonical faction for this assigned case target.",()->factions(p,c)));
   if(c.economy()&&c.suspect()!=null)choices.add(choice(p,"Wallet correction","Conserved transfer between suspect wallet and network treasury. No currency creation.",()->economy(p,c)));
  }
  choices.add(choice(p,"Refresh","Reload assignment, context and action availability.",()->openCase(p,c.ticket())));choices.add(choice(p,"Cases","Return to your visible cases.",()->tickets(p)));
  show(p,"Case #"+c.ticket(),"Context version: "+c.version()+"\nAssigned agent: "+Objects.toString(c.assigned(),"Unassigned")+"\nCreator: "+Objects.toString(c.creator(),"Not verified/linked")+"\nSuspect: "+Objects.toString(c.suspect(),"Not selected")+"\nTarget actions require this case to remain assigned to you.",choices);
 }
 private void mutate(Player p,CaseBridge.Context c,String action,UUID suspect){if(action.equals("set-suspect")&&!CaseGuards.entry(p)){p.sendMessage("Case context permission changed.");return;}if(suspect!=null&&!CaseGuards.subjectChoice(p,getServer().getPlayer(suspect))){p.sendMessage("Suspect is no longer an eligible online identity.");return;}read(p,"Case · Saving",()->bridge.context(p.getUniqueId(),c.ticket(),action,c.version(),suspect),next->caseMenu(p,next));}
 private void suspects(Player p,CaseBridge.Context c){List<Screens.Choice> choices=new ArrayList<>();getServer().getOnlinePlayers().stream().filter(t->CaseGuards.subjectChoice(p,t)).sorted(Comparator.comparing(Player::getName)).limit(40).forEach(target->{UUID id=target.getUniqueId();choices.add(choice(p,target.getName(),"Actual online UUID: "+id,()->{Player current=getServer().getPlayer(id);if(CaseGuards.subjectChoice(p,current))show(p,"Confirm suspect",target.getName()+"\nUUID: "+id+"\nCase #"+c.ticket(),List.of(choice(p,"Confirm","Website must verify the real identity and current case authority.",()->mutate(p,c,"set-suspect",id)),choice(p,"Cancel","Keep existing suspect.",()->caseMenu(p,c))));}));});choices.add(choice(p,"Back","Return without changing the case.",()->caseMenu(p,c)));show(p,"Choose case suspect","Only current online player identities are offered; no offline UUID is guessed.",choices);}
 private void checkpoint(Player actor,Player target,boolean protectedAction,Consumer<Connection> operation)throws Exception{
  if(!CaseGuards.target(actor,target,protectedAction))throw new SQLException("Current online case authority required");
  target.closeInventory();fence.run(target,c->{if(!CaseGuards.target(actor,target,protectedAction))throw new IllegalStateException("Native authority changed");operation.accept(c);});
 }
 private void teleport(Player p,CaseBridge.Context c,boolean creator){UUID id=creator?c.creator():c.suspect();Player target=id==null?null:getServer().getPlayer(id);CaseStore.Action action=creator?CaseStore.Action.teleport_creator:CaseStore.Action.teleport_suspect;try{
  UUID receipt=UUID.randomUUID();checkpoint(p,target,false,sql->{try{store.authorise(sql,p.getUniqueId(),c.ticket(),c.version(),action,id);store.audit(sql,receipt,p.getUniqueId(),c.ticket(),c.version(),id,action,null,null,null,null,null);}catch(SQLException e){throw new IllegalStateException(e);}});
  // Position changes are intentionally after committed authorization/audit, not falsely treated as SQL-atomic.
  if(!CaseGuards.target(p,target,false)||!id.equals(target.getUniqueId()))throw new SQLException("Target disconnected");if(!p.teleport(target.getLocation()))throw new SQLException("Teleport cancelled");p.sendMessage("Moved to the authorised case "+(creator?"creator":"suspect")+".");
 }catch(Exception e){p.sendMessage("Case teleport was not completed. Refresh the case before retrying.");}}
 private void inventory(Player p,CaseBridge.Context c){Player target=c.suspect()==null?null:getServer().getPlayer(c.suspect());try{
  List<ItemView> items=new ArrayList<>();checkpoint(p,target,true,sql->{try{store.authorise(sql,p.getUniqueId(),c.ticket(),c.version(),CaseStore.Action.inspect_inventory,c.suspect());store.audit(sql,UUID.randomUUID(),p.getUniqueId(),c.ticket(),c.version(),c.suspect(),CaseStore.Action.inspect_inventory,null,null,null,null,null);ItemStack[] contents=target.getInventory().getContents();for(int slot=0;slot<Math.min(contents.length,41);slot++){ItemStack item=contents[slot];if(item!=null&&!item.getType().isAir())items.add(new ItemView(slot,item.clone(),item.serializeAsBytes()));}}catch(SQLException e){throw new IllegalStateException(e);}});
  List<Screens.Choice> choices=new ArrayList<>();for(ItemView item:items)choices.add(choice(p,"Slot "+item.slot+" · "+item.item.getType()+" ×"+item.item.getAmount(),itemDescription(item.item),()->itemMenu(p,c,item)));choices.add(choice(p,"Back","Return to the assigned case.",()->caseMenu(p,c)));show(p,"Suspect Inventory",target.getName()+" · "+target.getUniqueId()+"\nRead-only overview. Removal requires a separate exact-stack confirmation.",choices);
 }catch(Exception e){p.sendMessage("The exact suspect inventory could not be inspected. No items changed.");}}
 record ItemView(int slot,ItemStack item,byte[] bytes){}
 static String itemDescription(ItemStack item){var meta=item.getItemMeta();return "Amount: "+item.getAmount()+(meta!=null&&meta.hasDisplayName()?"\nName: "+meta.getDisplayName():"")+(meta!=null&&meta.hasLore()?"\n"+String.join("\n",meta.getLore()):"");}
 private void itemMenu(Player p,CaseBridge.Context c,ItemView item){List<Screens.Choice> choices=new ArrayList<>();if(c.edit()&&CaseGuards.action(p))choices.add(choice(p,"Confiscate exact stack","Remove this stack into durable case evidence. It is not transferred to your inventory.",()->confirmConfiscation(p,c,item)));choices.add(choice(p,"Back","Refresh the current inventory.",()->inventory(p,c)));show(p,"Inventory Slot "+item.slot,itemDescription(item.item),choices);}
 private void confirmConfiscation(Player p,CaseBridge.Context c,ItemView item){UUID receipt=UUID.randomUUID();show(p,"Confirm Confiscation","Case #"+c.ticket()+" · suspect "+c.suspect()+"\nSlot "+item.slot+" · "+item.item.getType()+" ×"+item.item.getAmount()+"\nExact item bytes must still match. Evidence is stored with this inventory checkpoint.",List.of(choice(p,"Confirm removal","No item is given to the staff member.",()->{
  Player target=getServer().getPlayer(c.suspect());try{checkpoint(p,target,true,sql->{try{ItemStack current=target.getInventory().getItem(item.slot);if(current==null||!MessageDigest.isEqual(current.serializeAsBytes(),item.bytes))throw new SQLException("Slot changed");store.confiscation(sql,receipt,p.getUniqueId(),c.ticket(),c.version(),c.suspect(),item.slot,item.bytes);target.getInventory().setItem(item.slot,null);}catch(SQLException e){throw new IllegalStateException(e);}});p.sendMessage("Exact stack confiscated into case evidence.");}catch(Exception e){p.sendMessage("Confiscation was not confirmed. Reopen the current inventory before retrying.");}openCase(p,c.ticket());}),choice(p,"Cancel","Leave the inventory unchanged.",()->inventory(p,c))));}
 private void factions(Player p,CaseBridge.Context c){
  Player target=c.suspect()==null?null:getServer().getPlayer(c.suspect());if(!CaseGuards.target(p,target,true)){p.sendMessage("Current eligible online suspect required.");return;}
  List<Screens.Choice> choices=new ArrayList<>();for(String faction:CaseStore.FACTIONS)choices.add(choice(p,faction,"Set the assigned suspect's faction membership to "+faction,()->confirmFaction(p,c,faction)));choices.add(choice(p,"Back","Leave faction membership unchanged.",()->caseMenu(p,c)));
  show(p,"Case Faction Assignment","Case #"+c.ticket()+" · suspect "+target.getName()+"\nUUID: "+c.suspect()+"\nOnly faction membership will change.",choices);
 }
 private void confirmFaction(Player p,CaseBridge.Context c,String faction){
  Player target=c.suspect()==null?null:getServer().getPlayer(c.suspect());if(!CaseGuards.target(p,target,true)||!CaseStore.FACTIONS.contains(faction))return;
  UUID receipt=UUID.randomUUID();show(p,"Confirm Faction Assignment","Case #"+c.ticket()+" · suspect "+target.getName()+"\nUUID: "+c.suspect()+"\nNew faction: "+faction+"\nOnly faction membership changes; this choice is recorded in the case audit.",List.of(choice(p,"Confirm faction","Current case, subject and native authority are checked inside the profile checkpoint.",()->{
   Player actual=getServer().getPlayer(c.suspect());try{if(!CaseGuards.target(p,actual,true))throw new SQLException("Target authority changed");actual.closeInventory();fence.assignFaction(p,actual,faction,sql->{try{if(!CaseGuards.target(p,actual,true))throw new SQLException("Native authority changed");store.factionChange(sql,receipt,p.getUniqueId(),c.ticket(),c.version(),c.suspect(),faction);}catch(SQLException e){throw new IllegalStateException(e);}});p.sendMessage("Case faction assignment committed and audited.");}catch(Exception unavailable){p.sendMessage("Faction assignment was not confirmed. Refresh the case before retrying.");}openCase(p,c.ticket());
  }),choice(p,"Cancel","Leave faction membership unchanged.",()->caseMenu(p,c))));
 }
 private void economy(Player p,CaseBridge.Context c){
  if(!CaseGuards.bank(p,true)&&!CaseGuards.bank(p,false)){p.sendMessage("Current independent staff-bank authority required.");return;}
  CaseStore.Balances[] balances=new CaseStore.Balances[1];Player target=getServer().getPlayer(c.suspect());
  try{checkpoint(p,target,true,sql->{try{balances[0]=store.balances(sql,p.getUniqueId(),c.ticket(),c.version(),c.suspect(),CaseGuards.bank(p,true));}catch(SQLException e){throw new IllegalStateException(e);}});}catch(Exception unavailable){p.sendMessage("Current case wallet and treasury could not be verified.");return;}
  List<Screens.Choice> choices=new ArrayList<>();for(boolean credit:List.of(true,false))if(CaseGuards.bank(p,credit))for(String amount:List.of("1.00","10.00","100.00","1000.00")){BigDecimal value=new BigDecimal(amount);choices.add(choice(p,(credit?"Credit ":"Recover ")+amount+" Dunemarks",credit?"Network treasury → suspect wallet":"Suspect wallet → network treasury",()->confirmCorrection(p,c,value,credit)));}choices.add(choice(p,"Back","Return without a transfer.",()->caseMenu(p,c)));show(p,"Case Wallet Correction","Suspect: "+c.suspect()+"\nWallet: "+balances[0].wallet().toPlainString()+" Dunemarks\nNetwork treasury: "+balances[0].treasury().toPlainString()+" Dunemarks\nExact cents conserved; no minting. Current staff bank authority is independently checked on confirmation.",choices);}
 private void confirmCorrection(Player p,CaseBridge.Context c,BigDecimal amount,boolean credit){UUID receipt=UUID.randomUUID();show(p,"Confirm Wallet Correction","Case #"+c.ticket()+" · suspect "+c.suspect()+"\n"+amount.toPlainString()+" Dunemarks\n"+(credit?"Network treasury → suspect wallet":"Suspect wallet → network treasury"),List.of(choice(p,"Confirm transfer","Current assignment, exact target, wallet and bank authority are checked again.",()->{Player target=getServer().getPlayer(c.suspect());try{if(!CaseGuards.bank(p,credit))throw new SQLException("Bank access changed");checkpoint(p,target,true,sql->{try{if(!CaseGuards.bank(p,credit))throw new SQLException("Bank access changed");store.correction(sql,receipt,p.getUniqueId(),c.ticket(),c.version(),c.suspect(),amount,credit);}catch(SQLException e){throw new IllegalStateException(e);}});p.sendMessage("Case correction transferred and audited.");}catch(Exception e){p.sendMessage("Correction was not confirmed. No automatic retry or replacement credit was issued.");}openCase(p,c.ticket());}),choice(p,"Cancel","No funds move.",()->caseMenu(p,c))));}
}




